using MessagePack;

[MessagePackObject]
public class Person
{
    [Key(0)] public string Name { get; set; } = string.Empty;
    [Key(1)] public int Age { get; set; }
}

// Serialize to bytes
byte[] bytes = MessagePackSerializer.Serialize(new Person { Name = "Alice", Age = 30 });

// Deserialize
Person person = MessagePackSerializer.Deserialize<Person>(bytes);
